import { NextResponse } from "next/server";
import { z } from "zod";
import { getSessionUser } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { isSameOriginJson } from "@/lib/request-security";

// Built-in Q/F content is generated by the curriculum. Only fields honored by both layouts are editable here.
export async function PATCH(request: Request) {
  if (!isSameOriginJson(request)) return NextResponse.json({ error: "Geçersiz istek kaynağı." }, { status: 403 });
  const user = await getSessionUser();
  if (!user || user.role !== "ADMIN" || user.isSuspended) return NextResponse.json({ error: "Yönetici yetkisi gerekir." }, { status: 403 });
  const parsed = z.object({ id: z.string().min(1).max(100), isPublished: z.boolean(), isPremium: z.boolean() }).strict().safeParse(await request.json().catch(() => null));
  if (!parsed.success) return NextResponse.json({ error: "Ders ayarları geçersiz." }, { status: 400 });
  try {
    const { id, ...data } = parsed.data;
    const updated = await prisma.lesson.updateMany({ where: { id }, data });
    return NextResponse.json(updated.count ? { ok: true } : { error: "Ders bulunamadı." }, { status: updated.count ? 200 : 404 });
  } catch { return NextResponse.json({ error: "Ders ayarları kaydedilemedi." }, { status: 503 }); }
}
